using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using IdleIntelligence.Core;
namespace IdleIntelligence.Runtime {
 public static class ItemV3ResearchDetails {
  public static bool Handles(GameState s,ItemInstance item)=>ItemSystemV3.Enabled(s)&&new[]{"experiment-controller","protocol-controller","lab-drone"}.Contains(item.type);
  public static string Copy(GameState s,string key){int locale=Math.Max(0,Array.IndexOf(SettingsCatalog.Languages,s.Settings.language));var c=CultureInfo.GetCultureInfo(s.Settings.language);return ItemV3Balance.ResearchStartCopy.First(row=>row.Id==key).Values[locale].Replace("{pair}",(ItemV3Balance.Get("combinations.autonomous.start")*100).ToString("0.##",c)).Replace("{interval}",ItemV3Balance.Get("combinations.autonomous.interval").ToString("0",c)).Replace("{third}",(ItemV3Balance.Get("combinations.autonomous.extra")*100).ToString("0.##",c));}
  static string F(GameState s,double n)=>Math.Abs(n)>=1e6?NumberFormatting.Format(ScientificNumber.From(n),s.Settings.numberFormat,s.Settings.language):n.ToString("0.###",CultureInfo.GetCultureInfo(s.Settings.language));
  public static string StoredStart(GameState s,Job job){if(job!=null&&job.researchStartVersion!=3)return "";var q=job==null?ItemSystemV3.ResearchStartQuote(s,"dataGeneration"):null;return Copy(s,"start").Replace("{value}",F(s,(job?.startingFraction??q?.startingFraction??0)*100)).Replace("{seconds}",F(s,job?.minimumSeconds??q?.minimumSeconds??0));}
  static double Potential(GameState s,ItemInstance item)=>item.type=="experiment-controller"?Math.Min(ItemV3Balance.Get("switch.cap"),ItemV3Balance.Get("switch.rate")*ItemSystemV3.AbilityStrength(s,item))*100:item.type=="protocol-controller"?Math.Max(ItemV3Balance.Get("protocol.floor"),ItemV3Balance.Get("protocol.minimumBase")/(1+ItemSystemV3.AbilityStrength(s,item))):Math.Min(ItemV3Balance.Get("drone.cap"),ItemV3Balance.Get("drone.rate")*ItemSystemV3.AbilityStrength(s,item))*100;
  static string Unique(GameState s,ItemInstance item)=>Copy(s,item.type=="experiment-controller"?"controller":item.type=="protocol-controller"?"protocol":"drone").Replace("{value}",F(s,Potential(s,item)));
  public static string Primary(GameState s,ItemInstance item)=>"<b>"+Unique(s,item)+"</b>";
  static double AreaFraction(GameState s){var item=ItemSystemV3.Equipped(s).FirstOrDefault(i=>i.type=="experiment-controller");return item==null?0:Potential(s,item);}
  public static string Text(GameState s,ItemInstance item,string requestedSlot=null){string lang=s.Settings.language;var lines=new List<string>{"<b>"+SettingsRules.Text(lang,"item:"+item.type)+"</b>",SettingsRules.Text(lang,"rarity:"+ItemBalance.Rarities[item.rarity])+" · Lv. "+item.level+(item.forge>0?" · "+SettingsRules.Text(lang,"game:forge")+" +"+item.forge:""),Unique(s,item)};var bonus=LegacyEffects.Factor(s,"item:research").Times(ItemV3Balance.Get("baseValue")*ItemSystemV3.Strength(item)*Workshop.Amplifier(s)*100);lines.Add(Copy(s,"base").Replace("{value}",NumberFormatting.Format(bonus,s.Settings.numberFormat,lang)));lines.Add(Copy(s,"slots"));bool worn=s.Workshop.equipped.Contains(item.id);string slot=Workshop.EquipmentSlot(s,item.id,requestedSlot);var preview=worn?ItemDetailRules.Upgrade(s,item.id):slot==null?null:new ItemRatePreview{Before=s,After=Workshop.Equip(s,item.id,slot),Slot=slot};if(preview!=null){var changes=new List<string>();void Metric(string key,double before,double after,bool lower=false,string unit=""){if(Math.Abs(after-before)<=1e-9)return;bool good=lower?after<before:after>before;changes.Add(Copy(s,key)+": "+F(s,before)+unit+" → <color="+(good?"#81F4AD":"#FF929B")+">"+F(s,after)+unit+"</color>");}void Production(string label,ScientificNumber before,ScientificNumber after){int compare=after.CompareTo(before);if(compare==0)return;string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat,lang);string a=N(before),b=N(after),delta=a==b?" ("+(compare>0?"+":"−")+N(compare>0?after.Subtract(before):before.Subtract(after))+")":"";changes.Add(label+": "+a+" → <color="+(compare>0?"#81F4AD":"#FF929B")+">"+b+delta+"</color>");}Production(SettingsRules.Text(lang,"game:credits")+"/s",Game.Income(preview.Before),Game.Income(preview.After));Production(SettingsRules.Text(lang,"game:data")+"/s",Game.DataRate(preview.Before),Game.DataRate(preview.After));Production(SettingsRules.Text(lang,"game:compute"),Game.Compute(preview.Before),Game.Compute(preview.After));Metric("speed",Game.ResearchSpeed(preview.Before),Game.ResearchSpeed(preview.After));Metric("minimum",ItemSystemV3.ResearchStartQuote(preview.Before,"dataGeneration").minimumSeconds,ItemSystemV3.ResearchStartQuote(preview.After,"dataGeneration").minimumSeconds,true,"\u00a0s");Metric("transfer",ItemSystemV3.ResearchTransferFraction(preview.Before)*100,ItemSystemV3.ResearchTransferFraction(preview.After)*100,false,"\u00a0%");Metric("area",AreaFraction(preview.Before),AreaFraction(preview.After),false,"\u00a0%");if(changes.Count>0){lines.Add("\n<b>"+UiLocalizedText.Translate(worn?"Nächstes Level":"Beim Anlegen",lang)+" · "+ItemPortrait.SlotName(preview.Slot,lang)+"</b>");lines.AddRange(changes);}}return string.Join("\n",lines);}
 }
}
